import type { ScreenContext } from '../keyboard-registry';

/**
 * What each box in the app is for. One entry per field, opened from the small "i" beside its label.
 * Rules for writers: describe what the code does today, in plain words. Names and numbers in examples are made up.
 * A test fails if a label has no entry here, or if an entry is not used on any screen.
 */
export interface FieldHelp {
  id: string;
  screen: ScreenContext;
  label: string;
  /** What this box represents. */
  means: string;
  /** Why the system needs it. */
  why: string;
  /** What to type. */
  enter: string;
  required: boolean;
  format: string;
  /** What happens when it is saved. */
  onSave: string;
  /** Which other parts of the app use it. */
  usedBy: string;
  mistakes: string;
  example: string;
  /** A Help guide with more. */
  article?: string;
}

const SAR = 'A number in SAR, such as 12.50.';
const TEXT = 'Ordinary text.';
const DAY = 'Pick a date from the calendar.';
const DIGITS = 'Numbers only.';

type Rest = Omit<FieldHelp, 'id' | 'screen' | 'label'>;
const f = (id: string, screen: ScreenContext, label: string, r: Rest): FieldHelp => ({ id, screen, label, ...r });

